const pick = (english, zh, en) => english ? en : zh;
const INCLUDE_RULE_COVERAGE = typeof GRAMMAR_RUNTIME === 'undefined' || !GRAMMAR_RUNTIME;

const roleLabels = {
  subject: ['主语', 'Subject'], predicate: ['谓语动词', 'Predicate verb'], auxiliary: ['助动词', 'Auxiliary'],
  modal: ['情态动词', 'Modal verb'], object: ['宾语', 'Object'], predicative: ['表语', 'Predicative'],
  objectComplement: ['宾语补足语', 'Object complement'], subjectComplement: ['主语补足语', 'Subject complement'],
  attribute: ['定语', 'Attribute'], adverbial: ['状语', 'Adverbial'], conjunction: ['连词', 'Conjunction'],
  marker: ['结构标记', 'Structure marker'], focus: ['焦点成分', 'Focused element'], parenthetical: ['插入语', 'Parenthetical'],
  omitted: ['省略成分', 'Omitted element'], clause: ['从句', 'Clause']
};

const part = (english, piece) => ({
  text: piece[0],
  role: piece[1],
  label: pick(english, piece[2] || (roleLabels[piece[1]] || [piece[1], piece[1]])[0], piece[3] || (roleLabels[piece[1]] || [piece[1], piece[1]])[1])
});

const hiddenNote = () => ({ visible: false, mode: '', title: '', body: '', detail: '' });
const structureNote = (english, zh, en) => ({
  visible: true,
  mode: 'structure',
  title: pick(english, '结构转换', 'Structure transformation'),
  body: pick(english, zh, en),
  detail: ''
});

const question = (english, data) => ({
  question: pick(english, data[0], data[1]),
  options: [
    { key: 'A', text: pick(english, data[2], data[3]) },
    { key: 'B', text: pick(english, data[4], data[5]) }
  ],
  answer: data[6],
  correct: pick(english, data[7], data[8]),
  wrong: pick(english, `再看规则：${data[7]}`, `Check the rule: ${data[8]}`)
});

const A = (ruleZh, ruleEn, pieces, q, noteZh, noteEn) => ({ ruleZh, ruleEn, pieces, q, noteZh, noteEn });
const Q = (zh, en, aZh, aEn, bZh, bEn, answer, whyZh, whyEn) => [zh, en, aZh, aEn, bZh, bEn, answer, whyZh, whyEn];

function makeLesson(english, spec, index) {
  if (!Array.isArray(spec.atoms) || spec.atoms.length < 3) throw new Error(`Each special-structure lesson needs at least three atomic rules: ${spec.id}`);
  const lesson = {
    id: spec.id,
    no: String(index + 1).padStart(2, '0'),
    level: spec.level,
    title: pick(english, spec.title[0], spec.title[1]),
    meta: pick(english, spec.meta[0], spec.meta[1]),
    examples: spec.atoms.map((atom) => atom.pieces.map((piece) => piece[0]).join(' ')),
    analyses: spec.atoms.map((atom) => atom.pieces.map((piece) => part(english, piece))),
    exampleNotes: spec.atoms.map((atom) => atom.noteZh ? structureNote(english, atom.noteZh, atom.noteEn) : hiddenNote()),
    rules: spec.atoms.map((atom) => pick(english, atom.ruleZh, atom.ruleEn)),
    ruleCoverage: INCLUDE_RULE_COVERAGE ? spec.atoms.map((_, atomIndex) => ({ exampleIndexes: [atomIndex], questionIndexes: [atomIndex] })) : [],
    questions: spec.atoms.map((atom) => question(english, atom.q))
  };
  if (lesson.examples.length !== lesson.questions.length || lesson.rules.length !== lesson.examples.length) throw new Error(`Unbalanced special-structure lesson: ${spec.id}`);
  return lesson;
}

